const leaseWorkflowOutbox = `-- name: LeaseWorkflowOutbox :many
WITH candidates AS (
    SELECT id FROM workflow_outbox
    WHERE status IN ('pending', 'leased')
      AND available_at <= now()
      AND (lease_expires_at IS NULL OR lease_expires_at < now())
    ORDER BY available_at, created_at
    FOR UPDATE SKIP LOCKED
    LIMIT $3
)
UPDATE workflow_outbox AS item
SET status = 'leased', lease_token = $1,
    lease_expires_at = now() + (CAST($2 AS bigint) * interval '1 second'),
    attempts = attempts + 1, updated_at = now()
FROM candidates WHERE item.id = candidates.id
RETURNING item.id, item.workspace_id, item.run_id, item.event_id, item.topic, item.event_key, item.payload, item.status, item.available_at, item.lease_token, item.lease_expires_at, item.attempts, item.last_error, item.published_at, item.created_at, item.updated_at
`

type LeaseWorkflowOutboxParams struct {
	LeaseToken   pgtype.UUID `json:"lease_token"`
	LeaseSeconds int64       `json:"lease_seconds"`
	BatchSize    int32       `json:"batch_size"`
}

func (q *Queries) LeaseWorkflowOutbox(ctx context.Context, arg LeaseWorkflowOutboxParams) ([]WorkflowOutbox, error) {
	rows, err := q.db.Query(ctx, leaseWorkflowOutbox, arg.LeaseToken, arg.LeaseSeconds, arg.BatchSize)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WorkflowOutbox{}
	for rows.Next() {
		var i WorkflowOutbox
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.RunID,
			&i.EventID,
			&i.Topic,
			&i.EventKey,
			&i.Payload,
			&i.Status,
			&i.AvailableAt,
			&i.LeaseToken,
			&i.LeaseExpiresAt,
			&i.Attempts,
			&i.LastError,
			&i.PublishedAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

