const releaseReadyWorkflowNodes = `-- name: ReleaseReadyWorkflowNodes :many
UPDATE workflow_node_execution AS successor
SET status = 'ready', revision = successor.revision + 1,
    ready_at = now(), updated_at = now()
WHERE successor.run_id = $1 AND successor.workspace_id = $2
  AND successor.status = 'waiting'
  AND NOT EXISTS (
      SELECT 1
      FROM workflow_node_dependency dependency
      JOIN workflow_node_execution predecessor ON predecessor.id = dependency.predecessor_node_id
      WHERE dependency.run_id = successor.run_id
        AND dependency.successor_node_id = successor.id
        AND predecessor.status <> 'succeeded'
  )
RETURNING successor.id, successor.workspace_id, successor.run_id, successor.node_key, successor.issue_id, successor.node_kind, successor.status, successor.revision, successor.fence_token, successor.active_attempt_id, successor.attempt_count, successor.executor_spec, successor.retry_policy, successor.verification_policy, successor.input_spec, successor.input_digest, successor.ready_at, successor.started_at, successor.completed_at, successor.next_retry_at, successor.failure_code, successor.failure_detail, successor.created_at, successor.updated_at
`

type ReleaseReadyWorkflowNodesParams struct {
	RunID       pgtype.UUID `json:"run_id"`
	WorkspaceID pgtype.UUID `json:"workspace_id"`
}

func (q *Queries) ReleaseReadyWorkflowNodes(ctx context.Context, arg ReleaseReadyWorkflowNodesParams) ([]WorkflowNodeExecution, error) {
	rows, err := q.db.Query(ctx, releaseReadyWorkflowNodes, arg.RunID, arg.WorkspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []WorkflowNodeExecution{}
	for rows.Next() {
		var i WorkflowNodeExecution
		if err := rows.Scan(
			&i.ID,
			&i.WorkspaceID,
			&i.RunID,
			&i.NodeKey,
			&i.IssueID,
			&i.NodeKind,
			&i.Status,
			&i.Revision,
			&i.FenceToken,
			&i.ActiveAttemptID,
			&i.AttemptCount,
			&i.ExecutorSpec,
			&i.RetryPolicy,
			&i.VerificationPolicy,
			&i.InputSpec,
			&i.InputDigest,
			&i.ReadyAt,
			&i.StartedAt,
			&i.CompletedAt,
			&i.NextRetryAt,
			&i.FailureCode,
			&i.FailureDetail,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const retryWorkflowOutbox = `-- name: RetryWorkflowOutbox :execrows
UPDATE workflow_outbox
SET status = CASE WHEN attempts >= $1 THEN 'dead' ELSE 'pending' END,
    available_at = $2, last_error = $3,
    lease_token = NULL, lease_expires_at = NULL, updated_at = now()
WHERE id = $4 AND lease_token = $5 AND status = 'leased'
`

